<?php
$active_menu='analytics';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'dashboards','view');$companyId=oecrm_current_company_id($conn);$year=(int)($_GET['year']??date('Y'));$hr=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(*) employees,(SELECT COUNT(*) FROM leave_requests WHERE company_id=$companyId AND status='pending') pending_leave,(SELECT COUNT(*) FROM attendance_sessions a JOIN employeestbl ae ON ae.id=a.employee_id WHERE ae.company_id=$companyId AND a.attendance_date=CURDATE()) attendance FROM employeestbl WHERE company_id=$companyId AND status=0"));$resource=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COUNT(DISTINCT CASE WHEN status='active' THEN employee_id END) allocated,SUM(CASE WHEN status='active' THEN billing_rate-salary_cost ELSE 0 END) margin FROM resource_allocations WHERE company_id=$companyId"));$finance=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COALESCE(SUM(total_amount),0) revenue,COALESCE(SUM(total_amount-paid_amount),0) outstanding FROM finance_invoices WHERE company_id=$companyId AND YEAR(invoice_date)=$year AND status<>'cancelled'"));$expense=mysqli_fetch_assoc(mysqli_query($conn,"SELECT COALESCE(SUM(amount),0) expense FROM finance_expenses WHERE company_id=$companyId AND YEAR(expense_date)=$year"));$trend=mysqli_query($conn,"SELECT m.month_no,COALESCE(i.revenue,0) revenue,COALESCE(e.expense,0) expense FROM (SELECT 1 month_no UNION SELECT 2 UNION SELECT 3 UNION SELECT 4 UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8 UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12)m LEFT JOIN(SELECT MONTH(invoice_date) month_no,SUM(total_amount) revenue FROM finance_invoices WHERE company_id=$companyId AND YEAR(invoice_date)=$year GROUP BY MONTH(invoice_date))i USING(month_no) LEFT JOIN(SELECT MONTH(expense_date) month_no,SUM(amount) expense FROM finance_expenses WHERE company_id=$companyId AND YEAR(expense_date)=$year GROUP BY MONTH(expense_date))e USING(month_no)");
?><div id="page-wrapper" class="compact-admin-page"><div class="foundation-titlebar"><span></span><h2>Management Analytics</h2></div><div class="resource-summary"><div><i class="fa fa-users"></i><span><small>Employees</small><strong><?php echo (int)$hr['employees'];?></strong></span></div><div><i class="fa fa-random"></i><span><small>Allocated Resources</small><strong><?php echo (int)$resource['allocated'];?></strong></span></div><div><i class="fa fa-line-chart"></i><span><small>Annual Revenue</small><strong><?php echo number_format($finance['revenue'],0);?></strong></span></div><div><i class="fa fa-money"></i><span><small>Outstanding</small><strong><?php echo number_format($finance['outstanding'],0);?></strong></span></div></div><div class="analytics-bands"><div class="panel panel-default"><div class="panel-heading">HR Snapshot</div><div class="panel-body"><p>Today's Attendance <strong><?php echo (int)$hr['attendance'];?></strong></p><p>Pending Leave Approvals <strong><?php echo (int)$hr['pending_leave'];?></strong></p></div></div><div class="panel panel-default"><div class="panel-heading">Resource Profitability</div><div class="panel-body"><p>Estimated Allocation Margin</p><strong class="analytics-big"><?php echo number_format($resource['margin'],2);?></strong></div></div><div class="panel panel-default"><div class="panel-heading">Financial Position</div><div class="panel-body"><p>Expenses <strong><?php echo number_format($expense['expense'],2);?></strong></p><p>Net Before Payroll <strong><?php echo number_format($finance['revenue']-$expense['expense'],2);?></strong></p></div></div></div><div class="panel panel-default"><div class="panel-heading">Revenue vs Expense Trend</div><div class="panel-body table-responsive"><table class="table foundation-table"><thead><tr><th>Month</th><th>Revenue</th><th>Expense</th><th>Net</th></tr></thead><tbody><?php while($r=mysqli_fetch_assoc($trend)):?><tr><td><?php echo date('F',mktime(0,0,0,$r['month_no'],1));?></td><td><?php echo number_format($r['revenue'],2);?></td><td><?php echo number_format($r['expense'],2);?></td><td><?php echo number_format($r['revenue']-$r['expense'],2);?></td></tr><?php endwhile;?></tbody></table></div></div></div><?php include 'footer.php';?>
